import{_ as l,r as e,o as c,c as u,e as t,a,d as s,s as o}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Mail - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[{"level":3,"title":"Driver prerequisites","slug":"driver-prerequisites","link":"#driver-prerequisites","children":[{"level":4,"title":"Mailgun driver","slug":"mailgun-driver","link":"#mailgun-driver","children":[]},{"level":4,"title":"SparkPost driver","slug":"sparkpost-driver","link":"#sparkpost-driver","children":[]},{"level":4,"title":"SES driver","slug":"ses-driver","link":"#ses-driver","children":[]}]}]},{"level":2,"title":"Sending mail","slug":"sending-mail","link":"#sending-mail","children":[{"level":4,"title":"Quick sending","slug":"quick-sending","link":"#quick-sending","children":[]},{"level":4,"title":"Building the message","slug":"building-the-message","link":"#building-the-message","children":[]},{"level":4,"title":"Mailing plain text","slug":"mailing-plain-text","link":"#mailing-plain-text","children":[]},{"level":4,"title":"Mailing parsed raw strings","slug":"mailing-parsed-raw-strings","link":"#mailing-parsed-raw-strings","children":[]},{"level":4,"title":"Mailing raw strings","slug":"mailing-raw-strings","link":"#mailing-raw-strings","children":[]},{"level":3,"title":"Attachments","slug":"attachments","link":"#attachments","children":[]},{"level":3,"title":"Inline attachments","slug":"inline-attachments","link":"#inline-attachments","children":[{"level":4,"title":"Embedding an image in mail content","slug":"embedding-an-image-in-mail-content","link":"#embedding-an-image-in-mail-content","children":[]},{"level":4,"title":"Embedding raw data in mail content","slug":"embedding-raw-data-in-mail-content","link":"#embedding-raw-data-in-mail-content","children":[]}]},{"level":3,"title":"Queueing mail","slug":"queueing-mail","link":"#queueing-mail","children":[{"level":4,"title":"Queueing a mail message","slug":"queueing-a-mail-message","link":"#queueing-a-mail-message","children":[]},{"level":4,"title":"Delayed message queueing","slug":"delayed-message-queueing","link":"#delayed-message-queueing","children":[]},{"level":4,"title":"Pushing to specific queues","slug":"pushing-to-specific-queues","link":"#pushing-to-specific-queues","children":[]}]}]},{"level":2,"title":"Message content","slug":"message-content","link":"#message-content","children":[{"level":3,"title":"Mail views","slug":"mail-views","link":"#mail-views","children":[{"level":4,"title":"Configuration section","slug":"configuration-section","link":"#configuration-section","children":[]}]},{"level":3,"title":"Using mail templates","slug":"using-mail-templates","link":"#using-mail-templates","children":[{"level":4,"title":"Automatically generated templates","slug":"automatically-generated-templates","link":"#automatically-generated-templates","children":[]}]},{"level":3,"title":"Using mail layouts","slug":"using-mail-layouts","link":"#using-mail-layouts","children":[]},{"level":3,"title":"Registering mail layouts, templates & partials","slug":"registering-mail-layouts-templates-partials","link":"#registering-mail-layouts-templates-partials","children":[]},{"level":3,"title":"Global variables","slug":"global-variables","link":"#global-variables","children":[]}]},{"level":2,"title":"Mail & local development","slug":"mail-local-development","link":"#mail-local-development","children":[{"level":4,"title":"Log driver","slug":"log-driver","link":"#log-driver","children":[]},{"level":4,"title":"Universal to","slug":"universal-to","link":"#universal-to","children":[]},{"level":4,"title":"Pretend mail mode","slug":"pretend-mail-mode","link":"#pretend-mail-mode","children":[]}]}],"relativePath":"1.x/services/mail.md","filePath":"1.x/services/mail.md"}'),r={name:"1.x/services/mail.md"};function g(d,n,k,m,h,v){const p=e("pre-heading"),i=e("post-heading");return c(),u("div",null,[t(p),n[0]||(n[0]=a("h1",null,"Mail",-1)),t(i),n[1]||(n[1]=a("h2",{id:"introduction"},[a("a",{href:"#introduction",class:"header-anchor"},"#"),s(" Introduction")],-1)),n[2]||(n[2]=a("p",null,[s("October provides drivers for SMTP, Mailgun, SparkPost, Amazon SES, PHP's "),a("code",null,"mail"),s(" function, and "),a("code",null,"sendmail"),s(", allowing you to quickly get started sending mail through a local or cloud based service of your choice. There are two ways to configure mail services, either using the back-end interface via "),a("em",null,"Settings > Mail settings"),s(" or by updating the default configuration values. In these examples we will update the configuration values.")],-1)),n[3]||(n[3]=a("h3",{id:"driver-prerequisites"},[a("a",{href:"#driver-prerequisites",class:"header-anchor"},"#"),s(" Driver prerequisites")],-1)),n[4]||(n[4]=a("p",null,[s("Before using the Mailgun, SparkPost or SES drivers you will need to install "),a("a",{href:"http://octobercms.com/plugin/october-drivers",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Drivers plugin"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(".")],-1)),n[5]||(n[5]=o(`<h4 id="mailgun-driver"><a href="#mailgun-driver" class="header-anchor">#</a> Mailgun driver</h4><p>To use the Mailgun driver, set the <code>driver</code> option in your <code>config/mail.php</code> configuration file to <code>mailgun</code>. Next, verify that your <code>config/services.php</code> configuration file contains the following options:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mailgun&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;domain&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-domain&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;endpoint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;api.mailgun.net&#39;</span><span class="token punctuation">,</span> <span class="token comment">// api.eu.mailgun.net for EU</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h4 id="sparkpost-driver"><a href="#sparkpost-driver" class="header-anchor">#</a> SparkPost driver</h4><p>To use the SparkPost driver set the <code>driver</code> option in your <code>config/mail.php</code> configuration file to <code>sparkpost</code>. Next, verify that your <code>config/services.php</code> configuration file contains the following options:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;sparkpost&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-sparkpost-key&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h4 id="ses-driver"><a href="#ses-driver" class="header-anchor">#</a> SES driver</h4><p>To use the Amazon SES driver set the <code>driver</code> option in your <code>config/mail.php</code> configuration file to <code>ses</code>. Then, verify that your <code>config/services.php</code> configuration file contains the following options:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;ses&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-secret&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;region&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ses-region&#39;</span><span class="token punctuation">,</span>  <span class="token comment">// e.g. us-east-1</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="sending-mail"><a href="#sending-mail" class="header-anchor">#</a> Sending mail</h2><p>To send a message, use the <code>send</code> method on the <code>Mail</code> facade which accepts three arguments. The first argument is a unique <em>mail code</em> used to locate either the <a href="#mail-views">mail view</a> or <a href="#mail-templates">mail template</a>. The second argument is an array of data you wish to pass to the view. The third argument is a <code>Closure</code> callback which receives a message instance, allowing you to customize the recipients, subject, and other aspects of the mail message:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// These variables are available inside the message as Twig</span>
<span class="token variable">$vars</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Mary&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;This is a reminder&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Since we are passing an array containing the <code>name</code> key in the example above, we could display the value within our e-mail view using the following Twig markup:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><blockquote><p><strong>Note:</strong> You should avoid passing a <code>message</code> variable in your message, this variable is always passed and allows the <a href="#attachments">inline embedding of attachments</a>.</p></blockquote><h4 id="quick-sending"><a href="#quick-sending" class="header-anchor">#</a> Quick sending</h4><p>October also includes an alternative method called <code>sendTo</code> that can simplify sending mail:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Send to address using no name</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send using an object&#39;s properties</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send to multiple addresses</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Alternatively send a raw message without parameters</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">rawTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Hello friend&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The first argument in <code>sendTo</code> is used for the recipients can take different value types:</p><div class="table"><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>String</td><td>a single recipient address, with no name defined.</td></tr><tr><td>Array</td><td>multiple recipients where the array key is the address and the value is the name.</td></tr><tr><td>Object</td><td>a single recipient object, where the <em>email</em> property is used for the address and the <em>name</em> is optionally used for the name.</td></tr><tr><td>Collection</td><td>a collection of recipient objects, as above.</td></tr></tbody></table></div><p>The complete signature of <code>sendTo</code> is as follows:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$recipient</span><span class="token punctuation">,</span> <span class="token variable">$message</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><ul><li><code>$recipient</code> is defined as above.</li><li><code>$message</code> is the template name or message contents for raw sending.</li><li><code>$params</code> array of variables made available inside the template.</li><li><code>$callback</code> gets called with one parameter, the message builder as described for the <code>send</code> method (optional, defaults to null). If not a callable value, works as a substitute for the next options argument.</li><li><code>$options</code> custom sending options passed as an array (optional)</li></ul><p>The following custom sending <code>$options</code> are supported</p><ul><li><strong>queue</strong> specifies whether to queue the message or send it directly (optional, defaults to false).</li><li><strong>bcc</strong> specifies whether to add recipients as Bcc or regular To addresses (defaults to false).</li></ul><h4 id="building-the-message"><a href="#building-the-message" class="header-anchor">#</a> Building the message</h4><p>As previously mentioned, the third argument given to the <code>send</code> method is a <code>Closure</code> allowing you to specify various options on the e-mail message itself. Using this Closure you may specify other attributes of the message, such as carbon copies, blind carbon copies, etc:</p><div class="language-php extra-class"><pre class="language-php"><code>    <span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

        <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;us@example.com&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.com&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;bar@example.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Here is a list of the available methods on the <code>$message</code> message builder instance:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">sender</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">bcc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">replyTo</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token variable">$subject</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">priority</span><span class="token punctuation">(</span><span class="token variable">$level</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Attach a file from a raw $data string...</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attachData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Get the underlying SwiftMailer message instance...</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">getSwiftMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,30)),n[6]||(n[6]=a("blockquote",null,[a("p",null,[a("strong",null,"Note:"),s(" The message instance passed to a "),a("code",null,"Mail::send"),s(" Closure extends the "),a("a",{href:"http://swiftmailer.org",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("SwiftMailer"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(" message class, allowing you to call any method on that class to build your e-mail messages.")])],-1)),n[7]||(n[7]=o(`<h4 id="mailing-plain-text"><a href="#mailing-plain-text" class="header-anchor">#</a> Mailing plain text</h4><p>By default, the view given to the <code>send</code> method is assumed to contain HTML. However, by passing an array as the first argument to the <code>send</code> method, you may specify a plain text view to send in addition to the HTML view:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog::mail.html&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.text&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Or, if you only need to send a plain text e-mail, you may specify this using the <code>text</code> key in the array:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.text&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="mailing-parsed-raw-strings"><a href="#mailing-parsed-raw-strings" class="header-anchor">#</a> Mailing parsed raw strings</h4><p>You may use the <code>raw</code> method if you wish to e-mail a raw string directly. This content will be parsed by Markdown.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Text to e-mail&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Additionally this string will be parsed by Twig, if you wish to pass variables to this environment, use the <code>send</code> method instead, passing the content as the <code>raw</code> key.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;raw&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Text to email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="mailing-raw-strings"><a href="#mailing-raw-strings" class="header-anchor">#</a> Mailing raw strings</h4><p>If you pass an array containing either <code>text</code> or <code>html</code> keys, this will be an explicit request to send mail. No layout or markdown parsing is used.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is plain text&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;html&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&lt;strong&gt;This is HTML&lt;/strong&gt;&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="attachments"><a href="#attachments" class="header-anchor">#</a> Attachments</h3><p>To add attachments to an e-mail, use the <code>attach</code> method on the <code>$message</code> object passed to your Closure. The <code>attach</code> method accepts the full path to the file as its first argument:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>

    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When attaching files to a message, you may also specify the display name and / or MIME type by passing an <code>array</code> as the second argument to the <code>attach</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;as&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$display</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;mime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$mime</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="inline-attachments"><a href="#inline-attachments" class="header-anchor">#</a> Inline attachments</h3><h4 id="embedding-an-image-in-mail-content"><a href="#embedding-an-image-in-mail-content" class="header-anchor">#</a> Embedding an image in mail content</h4><p>Embedding inline images into your e-mails is typically cumbersome; however, there is a convenient way to attach images to your e-mails and retrieving the appropriate CID. To embed an inline image, use the <code>embed</code> method on the <code>message</code> variable within your e-mail view. Remember, the <code>message</code> variable is available to all of your mail views:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If you are planning to use queued emails make sure that the path of the file is absolute. To achieve that you can simply use the <a href="./../markup/filter-app.html">app filter</a>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> pathToFile <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>storage/app/media/path/to/file.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>app <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="embedding-raw-data-in-mail-content"><a href="#embedding-raw-data-in-mail-content" class="header-anchor">#</a> Embedding raw data in mail content</h4><p>If you already have a raw data string you wish to embed into an e-mail message, you may use the <code>embedData</code> method on the <code>message</code> variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image from raw data:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embedData<span class="token punctuation">(</span>data<span class="token punctuation">,</span> name<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="queueing-mail"><a href="#queueing-mail" class="header-anchor">#</a> Queueing mail</h3><h4 id="queueing-a-mail-message"><a href="#queueing-a-mail-message" class="header-anchor">#</a> Queueing a mail message</h4><p>Since sending mail messages can drastically lengthen the response time of your application, many developers choose to queue messages for background sending. This is easy using the built-in <a href="./../services/queues.html">unified queue API</a>. To queue a mail message, use the <code>queue</code> method on the <code>Mail</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This method will automatically take care of pushing a job onto the queue to send the mail message in the background. Of course, you will need to <a href="./../services/queues.html">configure your queues</a> before using this feature.</p><h4 id="delayed-message-queueing"><a href="#delayed-message-queueing" class="header-anchor">#</a> Delayed message queueing</h4><p>If you wish to delay the delivery of a queued e-mail message, you may use the <code>later</code> method. To get started, simply pass the number of seconds by which you wish to delay the sending of the message as the first argument to the method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">later</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="pushing-to-specific-queues"><a href="#pushing-to-specific-queues" class="header-anchor">#</a> Pushing to specific queues</h4><p>If you wish to specify a specific queue on which to push the message, you may do so using the <code>queueOn</code> and <code>laterOn</code> methods:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queueOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">laterOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::mail.welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="message-content"><a href="#message-content" class="header-anchor">#</a> Message content</h2><p>Mail messages can be sent in October using either mail views or mail templates. A mail view is supplied by the application or plugin in the file system in the <strong>/views</strong> directory. Whereas a mail template is managed using the back-end interface via <em>System &gt; Mail templates</em>. All mail messages support using Twig for markup.</p><p>Optionally, mail views can be <a href="#registering-mail-layouts-templates-partials">registered in the Plugin registration file</a> with the <code>registerMailTemplates</code> method. This will automatically generate a mail template and allows them to be customized using the back-end interface.</p><h3 id="mail-views"><a href="#mail-views" class="header-anchor">#</a> Mail views</h3><p>Mail views reside in the file system and the code used represents the path to the view file. For example sending mail with the code <strong>author.plugin::mail.message</strong> would use the content in following file:</p><div class="language- extra-class"><pre class="language-text"><code>plugins/               &lt;=== Plugins Directory
  author/              &lt;=== &quot;author&quot; Segment
    plugin/            &lt;=== &quot;plugin&quot; Segment
      views/           &lt;=== View Directory
        mail/          &lt;=== &quot;mail&quot; Segment
          message.htm  &lt;=== &quot;message&quot; Segment
</code></pre></div><p>The content inside a mail view file can include up to 3 sections: <strong>configuration</strong>, <strong>plain text</strong>, and <strong>HTML markup</strong>. Sections are separated with the <code>==</code> sequence. For example:</p><div class="language-twig extra-class"><pre class="language-twig"><code>subject = &quot;Your product has been added to OctoberCMS project&quot;
==

Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

Good news! User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.

This message was sent using no formatting (plain text)
==

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Good news! User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>strong</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>strong</span><span class="token punctuation">&gt;</span></span> to a project.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This email was sent using formatting (HTML)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note:</strong> Basic Twig tags and expressions are supported in mail views.</p></blockquote><p>The <strong>plain text</strong> section is optional and a view can contain only the configuration and HTML markup sections.</p><div class="language-twig extra-class"><pre class="language-twig"><code>subject = &quot;Your product has been added to OctoberCMS project&quot;
==

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This email does not support plain text.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Sorry about that!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="configuration-section"><a href="#configuration-section" class="header-anchor">#</a> Configuration section</h4><p>The configuration section sets the mail view parameters. The following configuration parameters are supported:</p><div class="table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>subject</strong></td><td>the mail message subject, required.</td></tr><tr><td><strong>layout</strong></td><td>the <a href="#mail-layouts">mail layout</a> code, optional. Default value is <code>default</code>.</td></tr></tbody></table></div><h3 id="using-mail-templates"><a href="#using-mail-templates" class="header-anchor">#</a> Using mail templates</h3><p>Mail templates reside in the database and can be created in the back-end area via <em>Settings &gt; Mail &gt; Mail templates</em>. The <strong>code</strong> specified in the template is a unique identifier and cannot be changed once created.</p><p>The process for sending these emails is the same. For example, if you create a template with code <em>this.is.my.email</em> you can send it using this PHP code:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;this.is.my.email&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note:</strong> If the mail template does not exist in the system, this code will attempt to find a mail view with the same code.</p></blockquote><h4 id="automatically-generated-templates"><a href="#automatically-generated-templates" class="header-anchor">#</a> Automatically generated templates</h4><p>Mail templates can also be generated automatically by <a href="#registering-mail-layouts-templates-partials">mail views that have been registered</a>. The <strong>code</strong> value will be the same as the mail view path (eg: author.plugin:mail.message). If the mail view has a <strong>layout</strong> parameter defined, this will be used to give the template a layout.</p><p>When a generated template is saved for the first time, the customized content will be used when sending mail for the assigned code. In this context, the mail view can be considered a <em>default view</em>.</p><h3 id="using-mail-layouts"><a href="#using-mail-layouts" class="header-anchor">#</a> Using mail layouts</h3><p>Mail layouts can be created by selecting <em>Settings &gt; Mail &gt; Mail templates</em> and clicking the <em>Layouts</em> tab. These behave just like CMS layouts, they contain the scaffold for the mail message. Mail views and templates support the use of mail layouts.</p><p>By default, October comes with two primary mail layouts:</p><div class="table"><table tabindex="0"><thead><tr><th>Layout</th><th>Code</th><th>Description</th></tr></thead><tbody><tr><td>Default</td><td>default</td><td>Used for public facing, front-end mail</td></tr><tr><td>System</td><td>system</td><td>Used for internal, back-end mail</td></tr></tbody></table></div><h3 id="registering-mail-layouts-templates-partials"><a href="#registering-mail-layouts-templates-partials" class="header-anchor">#</a> Registering mail layouts, templates &amp; partials</h3><p>Mail views can be registered as templates that are automatically generated in the back-end ready for customization. Mail templates can be customized via the <em>Settings &gt; Mail templates</em> menu. The templates can be registered by overriding the <code>registerMailTemplates</code> method of the <a href="./../plugin/registration.html#registration-file">Plugin registration class</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;rainlab.user::mail.activate&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;rainlab.user::mail.restore&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The method should return an array of <a href="#mail-views">mail view names</a>.</p><p>Like templates, mail partials and layouts can be registered by overriding the <code>registerMailPartials</code> and <code>registerMailLayouts</code> methods of the <a href="./../plugin/registration.html#registration-file">Plugin registration class</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;tracking&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.tracking&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;promotion&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.promotion&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;marketing&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.marketing&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;notification&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.notification&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The methods should return an array of <a href="#mail-views">mail view names</a>. The array key will be used as <code>code</code> property for the partial or layout.</p><h3 id="global-variables"><a href="#global-variables" class="header-anchor">#</a> Global variables</h3><p>You may register variables that are globally available to all mail templates with the <code>View::share</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;OctoberCMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This code could be called inside the register or boot method of a <a href="./../plugin/registration.html">plugin registration file</a>. Using the above example, the variable <code>{{ site_name }}</code> will be available inside all mail templates.</p><h2 id="mail-local-development"><a href="#mail-local-development" class="header-anchor">#</a> Mail &amp; local development</h2><p>When developing an application that sends e-mail, you probably don&#39;t want to actually send e-mails to live e-mail addresses. There are several ways to &quot;disable&quot; the actual sending of e-mail messages.</p><h4 id="log-driver"><a href="#log-driver" class="header-anchor">#</a> Log driver</h4><p>One solution is to use the <code>log</code> mail driver during local development. This driver will write all e-mail messages to your log files for inspection. For more information on configuring your application per environment, check out the <a href="./../setup/configuration.html">configuration documentation</a>.</p><h4 id="universal-to"><a href="#universal-to" class="header-anchor">#</a> Universal to</h4><p>Another solution is to set a universal recipient of all e-mails sent by the framework. This way, all the emails generated by your application will be sent to a specific address, instead of the address actually specified when sending the message. This can be done via the <code>to</code> option in your <code>config/mail.php</code> configuration file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;to&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dev@example.com&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Dev Example&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h4 id="pretend-mail-mode"><a href="#pretend-mail-mode" class="header-anchor">#</a> Pretend mail mode</h4><p>You can dynamically disable sending mail using the <code>Mail::pretend</code> method. When the mailer is in pretend mode, messages will be written to your application&#39;s log files instead of being sent to the recipient.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">pretend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,85))])}const y=l(r,[["render",g]]);export{b as __pageData,y as default};
